/* Lot 104: the layout geometry the engine hands back to the reader (generated by scripts/lot104_gen.py; expectations from scripts/lot104_model.py). */
#include "../../framework/unity.h"
#include <string.h>
#include <stdio.h>
#include "webeng.h"

static we_doc_t g_doc;
static wf_geom_t g_g;
static char g_html[4096], g_o[160];

/* the page laid out at 320 x 480: the boxes fed back */
static int page(const char *body) {
    snprintf(g_html, sizeof(g_html), "<html><body style='margin:0'>%s</body></html>", body);
    if (we_parse(&g_doc, g_html, (int)strlen(g_html)) || we_style(&g_doc) || we_layout_viewport(&g_doc, 320, 480))
        return -9;
    memset(&g_g, 0x5a, sizeof(g_g));
    return we_geom_feed(&g_doc, "wg", &g_g);
}

static const char *root(void) {
    snprintf(g_o, sizeof(g_o), "%d %d %d %d", g_g.vw, g_g.vh, g_g.rg_x, g_g.rg_y);
    return g_o;
}

static const char *box(int k) {
    const wf_geom_box_t *b = &g_g.box[k];
    if (!b->ok) return "none";
    snprintf(g_o, sizeof(g_o), "%d %d %d+%d %d+%d vp %d/%d rg %d/%d", b->root, b->bvert, b->b_off, b->b_size,
             b->i_off, b->i_size, b->vp_b, b->vp_i, b->rg_b, b->rg_i);
    return g_o;
}

